{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Personal-training sessions can be booked with `book_session` only with trainers whose `certified_for` list includes the requested session type, and only in free slots returned by `get_trainer_slots`.",
      "requirement": "The `trainer_id` must belong to a trainer whose `certified_for` list includes the `session_type` specified in the `book_session` call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Personal-training sessions can be booked with `book_session` only with trainers whose `certified_for` list includes the requested session type, and only in free slots returned by `get_trainer_slots`.",
      "requirement": "The `slot` must be one of the free slots returned by a `get_trainer_slots` call for the specified `trainer_id` and date, made no earlier than the last confirmation of the slot's availability."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- A member can hold at most 4 future sessions at a time.",
      "requirement": "The member’s total number of future sessions (including the one being booked) must not exceed 4."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Identify the member with `get_member` (member ID). The member must state their date of birth, and it must match the profile, before any change.",
      "requirement": "The `member_id` must match the account holder who explicitly stated their date of birth, and the stated date of birth must match the profile."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Only the account holder can make changes to their membership. A family member or friend cannot authorise changes on the holder's behalf.",
      "requirement": "The action must be authorized by the account holder (not a family member or friend)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Before `freeze_membership`, `change_plan`, `book_session`, `cancel_session` and `issue_guest_pass`, list the details and get explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation (\"yes\" or \"да\") from the member must be obtained before making the `book_session` call, after listing the booking details."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- Optional arguments may be omitted; do not invent values for them.",
      "requirement": "The `towel_service` argument, if included, must reflect the member’s actual preference; it cannot be invented or assumed."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "- book_session — Book a personal-training session.\n    member_id: string! — Member ID.\n    trainer_id: string! — Trainer ID.\n    slot: string! — YYYY-MM-DDTHH:MM\n    session_type: string! [enum: strength|mobility|boxing|swim] — Type.\n    towel_service: boolean — Optional towel service.",
      "requirement": "The `member_id` must be a valid string matching the member’s account ID, and the `trainer_id` must be a valid string matching the trainer’s ID. The `slot` must be in the format `YYYY-MM-DDTHH:MM`, and the `session_type` must be one of the allowed values: `strength`, `mobility`, `boxing`, or `swim`."
    }
  ]
}

